/**
 * Business-day helper for owner registration. A registration date must fall on a
 * business day: a Saturday or Sunday rolls forward to the following Monday. Used for
 * the effective registration date (supplied in the request or defaulted to the server
 * date) and for anything derived from it (membership number year, daily create-limit).
 */
final class BusinessDays {

    private BusinessDays() {
    }

    /** Rolls {@code date} forward to the next business day: a weekend becomes Monday. */
    static LocalDate rollToBusinessDay(LocalDate date) {
        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
            date = date.plusDays(1);
        }
        return date;
    }
}

